import React, { useState } from "react";
import { Modal, Button } from "react-bootstrap";

export default function ProjectsSection({ bg, textColor, height }) {
  const [selectedProject, setSelectedProject] = useState(null);

  const projects = [
    { id: 1, title: "Transcendence", image: "/transcendence-screen1.png", description: "Application Web d'un jeu pong en réseau via Django" },
    { id: 2, title: "Minishell", image: "/minishell-screen1.png", description: "Mini shell avec variables d'environnement, redirections, heredoc" },
    { id: 3, title: "Cube3D", image: "/cube3D-screen1.png", description: "Raycasting en C avec textures et parsing des maps" },
    { id: 4, title: "Portfolio", image: "/portfolio-screen1.png", description: "Portfolio React/Bootstrap" },
    { id: 5, title: "Projet 5", image: "/project.jpg", description: "Description projet 5" },
    { id: 6, title: "Projet 6", image: "/project.jpg", description: "Description projet 6" },
  ];

  return (
    <section
      id="projets"
      className={`${bg} ${textColor}`}
      style={{
        scrollMarginTop: `${height}px`,
        backgroundImage: "url('/bg-projects.jpg')",
        backgroundSize: "cover",
        backgroundPosition: "top",
        backgroundRepeat: "no-repeat",
        width: "100%",
        padding: "4rem 0", // padding vertical
        overflowX: "hidden", // IMPORTANT: empêche le scroll horizontal
        boxSizing: "border-box",
      }}
    >
      <h2 className="text-center mb-5">Mes Projets</h2>

      <div className="container-fluid px-3"> {/* fluid + px-3 pour padding horizontal */}
        <div className="row gx-3 gy-4 justify-content-center">
          {projects.map((project) => (
            <div
              key={project.id}
              className="col-12 col-sm-6 col-md-4 d-flex"
              onClick={() => setSelectedProject(project)}
              style={{ cursor: "pointer" }}
            >
              <div className="card shadow-sm w-100">
                <img
                  src={project.image}
                  alt={project.title}
                  className="card-img-top"
                  style={{ objectFit: "cover", height: "200px" }}
                />
                <div className="card-body text-center">
                  <h5 className="card-title">{project.title}</h5>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Modal */}
      <Modal show={!!selectedProject} onHide={() => setSelectedProject(null)} centered>
        <Modal.Header closeButton>
          <Modal.Title>{selectedProject?.title}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <img src={selectedProject?.image} alt={selectedProject?.title} className="img-fluid rounded mb-3" />
          <p>{selectedProject?.description}</p>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setSelectedProject(null)}>Fermer</Button>
        </Modal.Footer>
      </Modal>
    </section>
  );
}
